function storeCollection(){return '<section id="professional-collection" class="bd-store-collection"><div class="bd-store-head"><span class="bd-kicker">PROFESSIONAL COLLECTION / FOUR EDITIONS</span><h2>Choose your operating system.</h2><p>Eight-sheet Excel workbook previews. Proposed one-time prices; checkout is not enabled.</p><a href="#free-resources">Start with free resources ↓</a></div><div class="bd-store-grid">'+STORE_ITEMS.map(p=>'<article class="bd-store-card" style="'+storeStyle(p)+'"><div class="bd-store-art">'+storeArt(p)+'</div><div class="bd-store-card-body"><span class="bd-store-edition">EDITION '+p.num+' / '+esc(p.track)+'</span><h3><a href="'+TOOLKIT+p.slug+'/">'+esc(p.name)+'</a></h3><p>'+esc(p.purpose)+'</p><div class="bd-store-price"><strong>$'+p.price+'</strong><span>Proposed · one-time</span></div><p class="bd-store-status">Preview only · not for sale</p><a class="bd-store-primary" href="'+TOOLKIT+p.slug+'/">Inspect workbook →</a><a class="bd-store-free" href="'+TOOLKIT+p.free+'-blank.csv" download>Free starter ↓</a></div></article>').join("")+'</div><details class="bd-store-compare"><summary>Compare free and professional resources</summary><div class="bd-store-access"><div><span>AVAILABLE NOW</span><h3>Free practice resources</h3><p>Four blank CSVs, four fictional examples and one Markdown workbook. No account or checkout.</p><a href="#free-resources">Browse downloads ↓</a></div><div><span>PREVIEW ONLY</span><h3>Professional workbooks</h3><p>Eight connected worksheets per product, local editing and fictional worked examples. Purchase and full-file delivery are not enabled.</p></div></div></details></section>'}
function storeProof(p){return '<section class="bd-store-proof" style="'+storeStyle(p)+'"><div class="bd-store-head"><span class="bd-kicker">INSIDE THE WORKBOOK / ILLUSTRATIVE VIEW</span><h2>Inspect the working record.</h2><p>'+esc(p.purpose)+'</p><a href="/business/instruments/'+p.instrument+'/">Try the free workbench ↗</a></div><div class="bd-store-spread"><div class="bd-store-art">'+storeArt(p)+'</div><div class="bd-store-sheet"><div class="bd-store-sheet-head"><span>ILLUSTRATIVE WORKSHEET</span><strong>'+esc(p.sheets[0])+' / '+esc(p.sheets[1])+'</strong></div><div class="bd-store-table-scroll" role="region" tabindex="0" aria-label="Fictional example worksheet, scroll if needed"><table><thead><tr>'+p.columns.map(x=>'<th scope="col">'+esc(x)+'</th>').join("")+'</tr></thead><tbody><tr>'+p.row.map(x=>'<td>'+esc(x)+'</td>').join("")+'</tr><tr aria-hidden="true">'+p.columns.map(()=>'<td>—</td>').join("")+'</tr></tbody></table></div><div class="bd-store-tabs">'+p.sheets.map(x=>'<span>'+esc(x)+'</span>').join("")+'</div><div class="bd-store-result"><small>'+esc(p.metric)+'</small><strong>'+esc(p.value)+'</strong></div><p>Illustrative layout and fictional values, not a screenshot of the actual workbook. '+(p.num==="04"?"*Only if required evidence and incident checks qualify.":"")+'</p></div></div><p class="bd-store-limit">'+esc(p.limit)+'</p><div class="bd-store-access"><div><span>AVAILABLE NOW</span><h3>Free starter file</h3><a href="'+TOOLKIT+p.free+'-blank.csv" download>Download blank CSV ↓</a><a href="'+TOOLKIT+p.free+'-example.csv" download>Download fictional example ↓</a></div><div><span>PROFESSIONAL PREVIEW</span><h3>$'+p.price+' proposed one-time</h3><p>No checkout, charge or premium-file delivery is available.</p><a href="'+TOOLKIT+'#professional-collection">Compare all four editions →</a></div></div></section>'}
function storeEnhance(path,content){if(path===TOOLKIT){const anchor='<section class="bd-section"><span class="bd-kicker">CHOOSE YOUR WORKSHEET</span>';if(!content.includes(anchor))return content;return content.replace(anchor,storeCollection()+'<section class="bd-section" id="free-resources"><span class="bd-kicker">AVAILABLE NOW / FREE DOWNLOADS</span>').replace(/<section class="bd-pro-teaser">[\s\S]*?<\/section>/g,"").replace("Four editable worksheets for work you can actually evaluate. Download a starter file, study a fictional example, then fill it with your own evidence.","Choose a free practice worksheet or inspect a professional operating workbook. Keep the evidence, calculations and decisions together.").replace('<small>Free · no account or checkout</small>','<small>Free · no account or checkout</small><nav class="bd-store-jump" aria-label="Resource collections"><a href="#professional-collection">Professional previews ↓</a><a href="#free-resources">Free downloads ↓</a></nav>')}const p=STORE_ITEMS.find(x=>path===TOOLKIT+x.slug+"/");if(!p)return content;return content.replace('<section class="bd-section"><span class="bd-kicker">WHAT IS INSIDE / VERSION 1.0</span>',storeProof(p)+'<section class="bd-section"><span class="bd-kicker">WHAT IS INSIDE / VERSION 1.0</span>').replace('class="bd-hero bd-pro-hero"','class="bd-hero bd-pro-hero bd-store-product" style="'+storeStyle(p)+'"')}

