function layout(title,desc,path,content,schema){content=storeEnhance(path,content);return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+' | AutoHustle Articles</title><meta name="description" content="'+esc(desc)+'"><link rel="canonical" href="'+BASE+path+'"><meta property="og:title" content="'+esc(title)+'"><meta property="og:description" content="'+esc(desc)+'"><meta property="og:url" content="'+BASE+path+'"><meta property="og:type" content="'+((path==="/business/"||path===TOOLKIT||path.startsWith(INSTRUMENTS)||path===SERVICE_PRODUCT||path===AUTOMATION_PRODUCT||NEW_PRO_PRODUCTS.some(p=>p.path===path))?"website":"article")+'"><script type="application/ld+json">'+JSON.stringify(schema).replace(/</g,"\\u003c")+'</script><style>'+css+STORE_CSS+'</style></head><body><a class="bd-skip" href="#content">Skip to content</a><header class="bd-mast"><a class="brand" href="/">AutoHustle Articles</a><nav aria-label="Main navigation"><a href="/">Articles</a><a href="/library/">Library</a><a href="'+STUDIO+'/#/curriculum">Paths</a></nav></header><main class="bd-shell" id="content">'+content+'</main><footer class="bd-footer"><a href="/">AutoHustle Articles</a><a href="/business/">Business &amp; AI</a><a href="/editorial/">Editorial standards</a><a href="/feed.xml">RSS</a><p>Educational guides. Examples are hypothetical unless explicitly labeled as signed operator notes. No earnings guarantees.</p></footer></body></html>'}
const filters=[["","All disciplines"],["service","Client services"],["automation","Automation"],["digital","Digital products"],["saas","Software"]];
const keywords={service:"customers clients local business discovery interviews offer pricing leads scope",automation:"ai workflow approvals retries duplicate idempotency safety invoice time savings",digital:"template worksheet spreadsheet download packaging customers product validation",saas:"software app launch tests acceptance security deployment booking errors rollback"};
function discover(params){const query=(params.get("q")||"").trim().slice(0,100),tokens=query.toLowerCase().split(/\s+/).filter(Boolean),track=filters.some(x=>x[0]===params.get("track"))?params.get("track"):"";const matches=guides.filter(g=>(!track||g.track===track)&&tokens.every(t=>[g.title,g.category,g.deck,g.sections.map(x=>x.join(" ")).join(" "),g.template,keywords[g.track]].join(" ").toLowerCase().includes(t)));return '<form class="bd-discover" action="/business/" method="get" role="search" aria-label="Search business field guides"><div><label for="bd-q">Find a guide</label><input id="bd-q" type="search" name="q" maxlength="100" value="'+esc(query)+'" placeholder="Try pricing, approval, templates…"></div><div><label for="bd-track">Discipline</label><select id="bd-track" name="track">'+filters.map(([id,label])=>'<option value="'+id+'"'+(id===track?' selected':'')+'>'+label+'</option>').join("")+'</select></div><button type="submit">Search</button><a href="/business/">Clear</a></form><p class="bd-count" role="status">'+matches.length+' of '+guides.length+' field guides'+(query?' matching “'+esc(query)+'”':'')+'</p>'+(matches.length?'<div class="bd-grid">'+matches.map(card).join("")+'</div>':'<div class="bd-empty"><h3>No matching field guides.</h3><p>Try a shorter phrase or select all disciplines. The general library has a separate archive search.</p><a href="/business/">Show all field guides</a> · <a href="/library/">Browse the full archive</a></div>')}

