function csvCell(x){return '"'+String(x??"").replace(/"/g,'""')+'"'}
function kitCsv(k,kind){const rows=kind==="example"?k.rows:k.rows.map((row,i)=>k.track==="service"?[row[0],"","",""]:k.track==="digital"?[row[0],"","","Not tested",""]:[row[0],"","","","Not run",""]);return [k.headers,...rows].map(row=>row.map(csvCell).join(",")).join("\r\n")+"\r\n"}
function workbook(){return "# AutoHustle — Practical work toolkit\n\nVersion 1.0 | November 27, 2026\n\nFree starter workbook. All examples are hypothetical; tests are not verified outcomes. Use fictional information or information you have permission to use.\n\n"+guides.map(g=>{const k=kitFor(g);return "## "+k.name+"\n\n"+k.summary+"\n\nField guide: "+BASE+uri(g)+"\nWorkshop: "+titlePath(g)+"\n\n### Practice worksheet\n\n"+g.template+"\n\n### Quality checks\n\n"+k.checks.map(x=>"- "+x).join("\n")+"\n\n### Files\n\nBlank: "+BASE+kitFile(k,"blank")+"\nExample: "+BASE+kitFile(k,"example")}).join("\n\n---\n\n")+"\n"}
