const INSTRUMENTS="/business/instruments/";
const instrumentSpecs=[{"slug":"service-quote-builder","track":"service","num":"01","title":"Service quote builder","head":"Price the job before promising it.","desc":"Calculate a defensible quote from labor, expenses, allocated overhead and a target contribution margin.","product":"service-operating-system","guide":"find-a-business-problem-worth-solving","fields":[["hours","Estimated labor hours",2,0,10000,"0.25"],["rate","Hourly labor cost ($)",20,0,100000,"0.01"],["direct","Supplies and travel ($)",20,0,1000000,"0.01"],["overhead","Allocated overhead ($)",10,0,1000000,"0.01"],["margin","Target margin (%)",35,0,95,"0.1"],["minimum","Minimum quote ($)",50,0,1000000,"0.01"]],"note":"Labor + direct expenses + allocated overhead = estimated cost. Target quote = cost ÷ (1 − target margin), rounded up to cents, subject to the minimum. Tax and unlisted costs are excluded. This is a planning estimate, not a market price."},{"slug":"automation-roi","track":"automation","num":"02","title":"Automation ROI workbench","head":"Measure the time you really save.","desc":"Compare manual work with reviewed automation and include recurring operating and setup costs.","product":"automation-operating-system","guide":"design-a-reliable-ai-automation-workflow","fields":[["runs","Runs per month",120,0,10000000,"1"],["manual","Manual minutes per run",8,0,100000,"0.1"],["review","Automated + review minutes per run",3,0,100000,"0.1"],["rate","Labor value per hour ($)",25,0,100000,"0.01"],["monthly","Monthly operating cost ($)",30,0,1000000,"0.01"],["setup","One-time setup cost ($)",220,0,1000000,"0.01"]],"note":"Reviewed time must include exception handling and human approval. Time value is modeled, not necessarily cash saved. Simple payback is undefined if monthly net value is zero or negative."},{"slug":"digital-product-pricing","track":"digital","num":"03","title":"Digital product pricing simulator","head":"Make every unit count.","desc":"Model percentage fees, flat fees, delivery costs, contribution and break-even before listing a product.","product":"digital-product-operating-system","guide":"build-a-digital-product-from-one-repeatable-task","fields":[["price","Sale price ($)",24,0,1000000,"0.01"],["percent","Percentage fee (%)",3,0,100,"0.1"],["flat","Fixed fee per sale ($)",0.3,0,100000,"0.01"],["delivery","Delivery cost per sale ($)",2,0,100000,"0.01"],["fixed","Fixed launch cost ($)",210,0,1000000,"0.01"],["units","Scenario units sold",25,0,10000000,"1"]],"note":"Fees are user-supplied assumptions, not current processor quotes. Contribution = price minus variable fees and delivery cost. Break-even rounds up to whole units. Taxes, refunds and other costs are excluded unless modeled."},{"slug":"software-release-evaluator","track":"saas","num":"04","title":"Software release evaluator","head":"Make release readiness explicit.","desc":"Evaluate required acceptance criteria, passing test coverage, blocking incidents and evidence without pretending to authorize deployment.","product":"software-launch-operating-system","guide":"test-a-small-ai-assisted-app-before-launch","fields":[["required","Required acceptance criteria",4,1,100000,"1"],["accepted","Criteria accepted with evidence",4,0,100000,"1"],["covered","Required criteria covered by passing tests",4,0,100000,"1"],["failed","Unresolved failed required tests",0,0,100000,"1"],["incidents","Open high/critical incidents",0,0,100000,"1"],["closure","Closed incidents missing evidence",0,0,100000,"1"],["rollback","Rollback rehearsed (0=no, 1=yes)",1,0,1,"1"],["usercheck","User-layer checks recorded (0=no, 1=yes)",1,0,1,"1"]],"note":"This evaluates self-reported counts, not individual test records. It cannot verify that coverage or evidence is genuine. Eligibility means ready for human review, not permission to deploy."}];
function instrumentCalc(spec,v){
 const money=n=>new Intl.NumberFormat("en-US",{style:"currency",currency:"USD"}).format(n);
 const num=n=>new Intl.NumberFormat("en-US",{maximumFractionDigits:2}).format(n);
 const cents=n=>Math.ceil(n*100-1e-8)/100;
 if(spec.track==="service"){const cost=v.hours*v.rate+v.direct+v.overhead,quote=Math.max(v.minimum,cents(cost/(1-v.margin/100)));return {primary:["Suggested quote",money(quote)],rows:[["Estimated cost",money(cost)],["Contribution after allocated overhead",money(quote-cost)],["Modeled margin",quote>0?num((quote-cost)/quote*100)+"%":"Not defined"]],state:quote===0?"Enter a positive cost or minimum quote.":"Estimate · review scope and market before offering."}}
 if(spec.track==="automation"){let h=v.runs*(v.manual-v.review)/60,g=h*v.rate,net=g-v.monthly;return {primary:["Monthly modeled net value",money(net)],rows:[["Net hours per month",num(h)+" h"],["Modeled gross labor value",money(g)],["Simple payback",net>0?num(v.setup/net)+" months":"Not achievable at these inputs"]],state:net>0?"Positive modeled net value; validate measured review time.":"Hold: modeled net value is not positive."}}
 if(spec.track==="digital"){let fee=v.price*v.percent/100+v.flat,c=v.price-fee-v.delivery;return {primary:["Contribution per sale",money(c)],rows:[["Contribution margin",v.price>0?num(c/v.price*100)+"%":"Not defined"],["Break-even sales",c>0?num(Math.ceil(v.fixed/c)):"Not achievable at these inputs"],["Scenario contribution after fixed launch cost",money(c*v.units-v.fixed)],["Modeled fee per sale",money(fee)]],state:c>0?"Positive unit contribution; test actual demand.":"Hold: nonpositive unit contribution."}}
 if(v.accepted>v.required||v.covered>v.required)return {error:"Accepted and covered criteria cannot exceed required criteria."};
 const blocks=[];if(v.accepted!==v.required)blocks.push("Acceptance criteria incomplete");if(v.covered!==v.required)blocks.push("Passing coverage incomplete");if(v.failed)blocks.push("Unresolved failed tests");if(v.incidents)blocks.push("Open high/critical incidents");if(v.closure)blocks.push("Closure evidence missing");if(!v.rollback)blocks.push("Rollback rehearsal missing");if(!v.usercheck)blocks.push("User-layer evidence missing");
 return {primary:["Review status",blocks.length?"Hold":"Eligible for human review"],rows:[["Accepted criteria",v.accepted+" / "+v.required],["Passing coverage",v.covered+" / "+v.required],["Blocking categories",String(blocks.length)],...blocks.map(b=>["Needs action",b])],state:blocks.length?"Resolve the listed blockers before requesting review.":"Self-reported inputs satisfy these checks; independently verify evidence before release."}
}
function readInstrument(spec,params){let v={},errors=[];for(const [key,label,initial,min,max,step] of spec.fields){const raw=params.get(key);let n=raw===null?initial:raw.trim()===""?NaN:Number(raw);if(!Number.isFinite(n)||n<min||n>max||(step==="1"&&!Number.isInteger(n))){errors.push(label+" must be a "+(step==="1"?"whole ":"")+"number from "+min+" to "+max+".");v[key]=initial}else v[key]=n}return {v,errors}}
