function instrumentFieldGroups(spec,fields){const groups={service:[["01","Job cost",["hours","rate","direct","overhead"]],["02","Pricing boundary",["margin","minimum"]]],automation:[["01","Workflow volume & time",["runs","manual","review"]],["02","Economics",["rate","monthly","setup"]]],digital:[["01","Unit economics",["price","percent","flat","delivery"]],["02","Launch scenario",["fixed","units"]]],saas:[["01","Acceptance evidence",["required","accepted","covered"]],["02","Blocking incidents & tests",["failed","incidents","closure"]],["03","Operational checks",["rollback","usercheck"]]]};return groups[spec.track].map(([num,title,keys])=>'<fieldset class="bd-field-group"><legend><span>'+num+'</span> '+esc(title)+'</legend><div class="bd-instrument-fields">'+keys.map(k=>fields[spec.fields.findIndex(x=>x[0]===k)]).join("")+'</div></fieldset>').join("")}

function instrumentPage(spec,params){const {v,errors}=readInstrument(spec,params);const result=errors.length?{error:errors.join(" ")}:instrumentCalc(spec,v);const fields=spec.fields.map(([key,label,initial,min,max,step])=>max===1&&min===0?'<div class="bd-instrument-field"><label for="inst-'+key+'">'+esc(label.replace(' (0=no, 1=yes)',''))+'</label><select required id="inst-'+key+'" name="'+key+'">'+(!['0','1'].includes(String(params.get(key)??initial))?'<option value="" selected>Choose an answer</option>':'')+'<option value="0"'+(String(params.get(key)??initial)==='0'?' selected':'')+'>No</option><option value="1"'+(String(params.get(key)??initial)==='1'?' selected':'')+'>Yes</option></select></div>':'<div class="bd-instrument-field"><label for="inst-'+key+'">'+esc(label)+'</label><input required type="number" name="'+key+'" id="inst-'+key+'" value="'+esc(String(params.get(key)??initial).slice(0,48))+'" min="'+min+'" max="'+max+'" step="'+(step==="1"?"1":"any")+'" inputmode="'+(step==="1"?"numeric":"decimal")+'"></div>');const html='<p class="bd-crumb"><a href="/business/">Business</a> / <a href="'+INSTRUMENTS+'">Instruments</a> / '+esc(spec.title)+'</p><section class="bd-tool-header" data-track="'+spec.track+'"><div><span class="bd-kicker">INSTRUMENT '+spec.num+' / PRACTICAL WORKBENCH</span><h1>'+esc(spec.title)+'</h1><p>'+esc(spec.desc)+'</p></div><div class="bd-tool-art">'+instrumentArt(spec)+'</div></section><section class="bd-tool-workspace" data-track="'+spec.track+'"><div class="bd-instrument-grid"><form class="bd-instrument-form" method="get" action="'+instrumentUri(spec)+'"><span class="bd-kicker">INPUT / ASSUMPTIONS</span><h2>Set the scenario.</h2><p class="bd-instrument-note" data-local-note>Example values are illustrative. Without JavaScript, calculations send numeric values in the URL; do not enter confidential information.</p>'+instrumentFieldGroups(spec,fields)+'<div class="bd-instrument-actions"><button type="submit">Calculate</button><button type="submit" name="export" value="csv">Export CSV ↓</button><a data-reset href="'+instrumentUri(spec)+'">Reset example</a></div></form><div class="bd-result-column"><section class="bd-instrument-result" aria-label="Calculated scenario results" aria-live="polite">'+instrumentResults(result)+'</section><div class="bd-chart-output" aria-label="Scenario visualization"></div></div></div><details class="bd-tool-method"><summary>Calculation method &amp; limitations</summary><p class="bd-instrument-note">'+esc(spec.note)+'</p></details>'+scenarioDesk()+'</section><section class="bd-kit-inline"><span class="bd-kicker">CONTINUE THE WORK</span><h2>From scenario to evidence.</h2><div class="bd-instrument-route"><a href="/business/'+spec.guide+'/">Read the companion field guide ↗</a><a href="'+STUDIO+'/#/track/'+spec.track+'">Open the free workshop ↗</a><a href="/business/toolkit/'+spec.product+'/">Preview the professional workbook ↗</a></div></section><section class="bd-section"><h2>Other instruments</h2>'+instrumentCards()+'</section>';return layout(spec.title,spec.desc,instrumentUri(spec),html,{"@context":"https://schema.org","@type":"WebApplication","name":spec.title,"url":BASE+instrumentUri(spec),"applicationCategory":"BusinessApplication","operatingSystem":"Web browser","offers":{"@type":"Offer","price":"0","priceCurrency":"USD"}}).replace("</body>",instrumentScript(spec)+"</body>")}
function instrumentResponse(request,u){const p=u.pathname;if(p===INSTRUMENTS.slice(0,-1))return Response.redirect(BASE+INSTRUMENTS+u.search,301);if(!p.startsWith(INSTRUMENTS))return null;const spec=instrumentSpecs.find(t=>p===instrumentUri(t)||p===instrumentUri(t).slice(0,-1));if(!spec&&p!==INSTRUMENTS)return new Response("Instrument not found.",{status:404,headers:{"content-type":"text/plain; charset=utf-8"}});if(spec&&p!==instrumentUri(spec))return Response.redirect(BASE+instrumentUri(spec)+u.search,301);if(spec&&u.searchParams.get("export")==="csv"){const {v,errors}=readInstrument(spec,u.searchParams),r=errors.length?{error:errors.join(" ")}:instrumentCalc(spec,v);if(r.error)return new Response(r.error,{status:400,headers:{"content-type":"text/plain; charset=utf-8","cache-control":"no-store"}});const rows=[["AutoHustle",spec.title],["Scenario","User-entered assumptions; not verified results"],["INPUT","VALUE"],...spec.fields.map(([k,l])=>[l,String(v[k])]),["RESULT","VALUE"],r.primary,...r.rows,["Caution",spec.note]];return kitDownload(request,spec.slug+"-scenario.csv",rows.map(row=>row.map(csvCell).join(",")).join("\r\n")+"\r\n","text/csv; charset=utf-8")}
let page=spec?instrumentPage(spec,u.searchParams):instrumentHub();if(u.search)page=page.replace("</head>",'<meta name="robots" content="noindex,follow"></head>');return new Response(request.method==="HEAD"?null:page,{headers:{"content-type":"text/html; charset=utf-8","cache-control":u.search?"no-store":"public,max-age=30","x-content-type-options":"nosniff","referrer-policy":"strict-origin-when-cross-origin","x-autohustle-release":"business-instruments-v3"}})}

function kitPage(){return layout("Practical work toolkit","Download editable client discovery, automation testing, digital product and app acceptance worksheets.",TOOLKIT,'<p class="bd-crumb"><a href="/">Articles</a> / <a href="/business/">Business, AI &amp; Automation</a> / Toolkit</p><section class="bd-hero"><div><span class="bd-kicker">AUTOHUSTLE / RESOURCE EDITION 01</span><h1>Keep the work.</h1><p>Four editable worksheets for work you can actually evaluate. Download a starter file, study a fictional example, then fill it with your own evidence.</p><p class="bd-kit-hero-action"><a href="'+TOOLKIT+'autohustle-starter-workbook.md" download>Download full workbook (.md) ↓</a><small>Free · no account or checkout</small></p></div><svg viewBox="0 0 300 215" role="img" aria-label="Illustration of stacked worksheets"><path d="M44 45H215V184H44Z" fill="#829981" stroke="#d2d7bd"/><path d="M56 32H230V170H56Z" fill="#b5bca3" stroke="#e5d9bd"/><path d="M70 18H245V155H70Z" fill="#fcf4e0" stroke="#e4d3b7" stroke-width="2"/><path d="M86 40H228M86 54H170M86 76H228M86 94H228M86 112H228M86 130H228M143 76V140" stroke="#526854" stroke-width="2"/><rect x="86" y="95" width="56" height="16" fill="#b96b50"/><circle cx="241" cy="153" r="28" fill="#a75335"/><path d="m229 153 8 8 16-18" stroke="#fcf4e0" stroke-width="3" fill="none"/><text x="44" y="205" font-size="8" fill="#e9dfc7" font-family="monospace">01 / RECORD • TEST • KEEP</text></svg></section><section class="bd-section"><span class="bd-kicker">CHOOSE YOUR WORKSHEET</span><h2>Four useful starting points.</h2><div class="bd-kit-grid">'+guides.map(g=>{const k=kitFor(g);return '<article class="bd-kit-card">'+art(g)+'<div><span class="bd-kicker">'+esc(g.category)+'</span><h3>'+esc(k.name)+'</h3><p>'+esc(k.summary)+'</p><ul>'+k.checks.map(x=>'<li>'+esc(x)+'</li>').join("")+'</ul>'+kitActions(k)+'<div class="bd-kit-links"><a href="'+uri(g)+'">Read companion guide ↗</a><a href="'+titlePath(g)+'">Open workshop ↗</a></div></div></article>'}).join("")+'</div></section><section class="bd-pro-teaser"><div><span class="bd-kicker">PROFESSIONAL RESOURCE / PREVIEW</span><h2>Service Operating System</h2><p>Eight connected workbook sheets for quoting, job records, payment evidence, direct costs and an operating dashboard. Proposed $19 one-time. Checkout not enabled.</p></div><a class="bd-kit-primary" href="/business/toolkit/service-operating-system/">Preview the workbook ↗</a></section><section class="bd-pro-teaser"><div><span class="bd-kicker">PROFESSIONAL RESOURCE 02 / PREVIEW</span><h2>Automation Operating System</h2><p>Eight connected workbook sheets for workflows, test evidence, dependencies, incidents and ROI. Proposed $29 one-time. Checkout not enabled.</p></div><a class="bd-kit-primary" href="/business/toolkit/automation-operating-system/">Preview the workbook ↗</a></section>'+newProTeasers()+instrumentPromo()+'<section class="bd-cta"><span class="bd-kicker">ACCESS &amp; USE</span><h2>Start free. Build something testable.</h2><p>CSV files open in compatible spreadsheet software; the Markdown workbook opens in a plain text editor. Save a local copy before editing. These are practice resources, not certifications or earnings guarantees. Paid membership and paid resource checkout are not offered on this page.</p><a href="'+STUDIO+'/#/curriculum">Continue in the free workshop ↗</a></section>',{"@context":"https://schema.org","@type":"CollectionPage","name":"AutoHustle Practical work toolkit","url":BASE+TOOLKIT,"description":"Four free editable practice resources"})}
function toolkitResponse(request,p){if(p===TOOLKIT+"autohustle-starter-workbook.md")return kitDownload(request,"autohustle-starter-workbook.md",workbook(),"text/markdown; charset=utf-8");for(const k of toolkit)for(const kind of ["blank","example"])if(p===kitFile(k,kind))return kitDownload(request,k.slug+"-"+kind+".csv",kitCsv(k,kind),"text/csv; charset=utf-8");return null}

function hub(params){return layout("Business, AI & Automation","Practical field guides for service work, reliable automation, digital products and small software projects.","/business/",'<p class="bd-crumb"><a href="/">Articles</a> / Business, AI &amp; Automation</p><section class="bd-hero"><div><span class="bd-kicker">AUTOHUSTLE / FIELD GUIDE DEPARTMENT</span><h1>Work that actually works.</h1><p>Four hands-on disciplines for turning ideas into useful outcomes. Read a practical guide, try the exercise, and take the result into the free AutoHustle workshop.</p></div><svg viewBox="0 0 300 215" aria-hidden="true"><path d="M20 18H280V197H20Z" fill="none" stroke="#839b86"/><path d="M50 50H125V100H50ZM175 50H250V100H175ZM50 130H125V180H50ZM175 130H250V180H175Z" fill="#faf3df" stroke="#aebea3" stroke-width="2"/><path d="M125 75H175M125 155H175M88 100V130M212 100V130" stroke="#e9c6a6" stroke-width="2" stroke-dasharray="4 4"/><path d="M65 62H110M65 73H104M65 84H93M187 63H201V85H187ZM224 63H238V85H224ZM201 74H224M65 144H110M65 155H110M83 144V168M98 144V168M188 145H236V166H188Z" fill="none" stroke="#354e43" stroke-width="2"/><circle cx="150" cy="115" r="19" fill="#b96b50"/><path d="m142 115 5 5 10-12" stroke="#fff7e6" stroke-width="2" fill="none"/><text x="30" y="191" fill="#e9dfc7" font-size="8" font-family="monospace">01 / DISCOVER • MAKE • VERIFY</text></svg></section><section class="bd-section"><span class="bd-kicker">START WITH A TASK</span><h2>Four field guides, four ways to build.</h2>'+discover(params)+'</section>'+instrumentPromo()+'<section class="bd-kit-inline"><span class="bd-kicker">FREE / WORKSHEETS</span><h2>Keep the work.</h2><p>Download editable starter files, fictional examples and a complete workbook for all four disciplines.</p><a class="bd-kit-primary" href="/business/toolkit/">Explore the practical toolkit ↗</a></section><section class="bd-section"><span class="bd-kicker">SIGNED OPERATOR NOTES</span><h2>From actual service operations.</h2><p class="bd-disclosure">First-person accounts, not independently verified business outcomes.</p><div class="bd-signed">'+signed.map(x=>'<a href="/'+x[0]+'/"><small>OPERATOR NOTE</small>'+esc(x[1])+' ↗</a>').join("")+'</div></section><section class="bd-cta"><span class="bd-kicker">PUT IT INTO PRACTICE</span><h2>Make the first usable version.</h2><p>Follow the corresponding free workshop path and create an artifact you can test.</p><a href="'+STUDIO+'/#/curriculum">Explore all four paths ↗</a></section>',{"@context":"https://schema.org","@type":"CollectionPage","name":"Business, AI & Automation","url":BASE+"/business/","description":"Practical educational field guides","hasPart":guides.map(g=>({"@type":"Article","name":g.title,"url":BASE+uri(g)}))})}
function reader(g){const path=uri(g),words=g.sections.map(x=>x.join(" ")).join(" ").split(/\s+/).length;const minutes=Math.max(3,Math.ceil(words/180));return layout(g.title,g.deck,path,'<p class="bd-crumb"><a href="/">Articles</a> / <a href="/business/">Business, AI &amp; Automation</a> / '+g.category+'</p><div class="bd-reader"><article><header><span class="bd-kicker">'+g.category+' / FIELD GUIDE '+g.num+'</span><h1>'+esc(g.title)+'</h1><p class="bd-deck">'+esc(g.deck)+'</p><p class="bd-meta">AutoHustle editorial desk · November 27, 2026 · '+minutes+' min read · Original educational guide</p></header><details class="bd-mobile-toc"><summary>In this guide</summary><ol>'+g.sections.map(([h],i)=>'<li><a href="#step-'+(i+1)+'">'+esc(h)+'</a></li>').join("")+'<li><a href="#worksheet">Practice worksheet</a></li></ol></details>'+art(g)+'<div class="bd-body">'+g.sections.map(([h,p],i)=>'<section id="step-'+(i+1)+'"><h2>'+esc(h)+'</h2><p>'+esc(p)+'</p></section>').join("")+'<section id="worksheet"><h2>Practice worksheet</h2><p>Copy this structure into your notes. Fill it using fictional data or information you have permission to use.</p><pre class="bd-template">'+esc(g.template)+'</pre>'+kitPanel(g)+'</section></div><section class="bd-cta"><span class="bd-kicker">NEXT / INTERACTIVE WORKSHOP</span><h2>'+esc(g.trackTitle)+'</h2><p>Use the free learning path to turn this guide into a practice artifact and record your own evidence.</p><a href="'+titlePath(g)+'">Open the learning path ↗</a></section><section class="bd-section"><h2>Continue reading</h2><div class="bd-grid">'+guides.filter(x=>x!==g).map(card).join("")+'</div>'+ (g.related.length?'<p class="bd-disclosure">Related signed operator notes:</p><ul>'+g.related.map(slug=>'<li><a href="/'+slug+'/">'+esc(signed.find(x=>x[0]===slug)?.[1]||slug)+'</a></li>').join("")+'</ul>':"")+'</section></article><aside class="bd-side"><span class="bd-kicker">IN THIS GUIDE</span><ol>'+g.sections.map(([h],i)=>'<li><a href="#step-'+(i+1)+'">'+esc(h)+'</a></li>').join("")+'<li><a href="#worksheet">Practice worksheet</a></li></ol><p><a href="/business/">All business field guides</a></p></aside></div>',{"@context":"https://schema.org","@type":"Article","headline":g.title,"description":g.deck,"datePublished":DATE,"dateModified":DATE,"author":{"@type":"Organization","name":"AutoHustle editorial desk"},"publisher":{"@type":"Organization","name":"AutoHustle"},"mainEntityOfPage":BASE+path,"articleSection":g.category})}
export function businessResponse(request){const u=new URL(request.url),p=u.pathname;if(p!=="/business"&&!p.startsWith("/business/"))return null;if(!["GET","HEAD"].includes(request.method))return new Response("Method not allowed",{status:405,headers:{Allow:"GET, HEAD"}});if(p==="/business")return Response.redirect(BASE+"/business/"+u.search,301);const instrument=instrumentResponse(request,u);if(instrument)return instrument;let page;if(p==="/business/toolkit")return Response.redirect(BASE+TOOLKIT+u.search,301);const file=toolkitResponse(request,p);if(file)return file;if(p===SERVICE_PRODUCT.slice(0,-1))return Response.redirect(BASE+SERVICE_PRODUCT+u.search,301);if(p===AUTOMATION_PRODUCT.slice(0,-1))return Response.redirect(BASE+AUTOMATION_PRODUCT+u.search,301);const newPro=NEW_PRO_PRODUCTS.find(x=>p===x.path||p===x.path.slice(0,-1));if(newPro&&p!==newPro.path)return Response.redirect(BASE+newPro.path+u.search,301);if(newPro)page=newProPage(newPro);else if(p===AUTOMATION_PRODUCT)page=automationProductPage();else if(p===SERVICE_PRODUCT)page=serviceProductPage();else if(p===TOOLKIT)page=kitPage();else if(p==="/business/"){page=hub(u.searchParams);if(u.searchParams.has("q")||u.searchParams.has("track"))page=page.replace("</head>",'<meta name="robots" content="noindex,follow"></head>')}else{const g=guides.find(x=>uri(x)===p||uri(x).slice(0,-1)===p);if(!g)return new Response("Field guide not found.",{status:404,headers:{"content-type":"text/plain; charset=utf-8","cache-control":"no-store"}});if(p!==uri(g))return Response.redirect(BASE+uri(g)+u.search,301);page=reader(g)}return new Response(request.method==="HEAD"?null:page,{headers:{"content-type":"text/html; charset=utf-8","cache-control":"public,max-age=30","x-content-type-options":"nosniff","referrer-policy":"strict-origin-when-cross-origin","x-autohustle-release":"business-department-v1"}})}
